-- Schema produced by crates/infra/audit/migrations, excluding dated day
-- partitions and _sqlx_migrations. Generated by the postgres_transaction_events
-- tests; regenerate with UPDATE_SCHEMA_SNAPSHOT=1 instead of editing by hand.

CREATE FUNCTION public.transaction_events_create_partition(p_class text, p_day date) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    parent_name TEXT;
    partition_name TEXT;
BEGIN
    IF p_class IS NULL OR p_class NOT IN ('hot', 'warm', 'cold') THEN
        RAISE EXCEPTION 'unknown transaction event retention class: %', p_class;
    END IF;
    IF p_day IS NULL THEN
        RAISE EXCEPTION 'transaction event partition day is required';
    END IF;

    parent_name := 'transaction_events_' || p_class;
    partition_name := parent_name || '_' || to_char(p_day, 'YYYYMMDD');
    IF to_regclass(format('public.%I', partition_name)) IS NOT NULL THEN
        RETURN FALSE;
    END IF;

    EXECUTE format(
        'CREATE TABLE public.%I (LIKE public.%I INCLUDING DEFAULTS)',
        partition_name,
        parent_name
    );
    EXECUTE format(
        'ALTER TABLE public.%I ATTACH PARTITION public.%I FOR VALUES FROM (%L) TO (%L)',
        parent_name,
        partition_name,
        to_char(p_day, 'YYYY-MM-DD'),
        to_char(p_day + 1, 'YYYY-MM-DD')
    );
    RETURN TRUE;
END;
$$;

CREATE FUNCTION public.transaction_events_detach_partition(p_class text, p_day date) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    parent_name TEXT;
    partition_name TEXT;
BEGIN
    IF p_class IS NULL OR p_class NOT IN ('hot', 'warm', 'cold') THEN
        RAISE EXCEPTION 'unknown transaction event retention class: %', p_class;
    END IF;
    IF p_day IS NULL THEN
        RAISE EXCEPTION 'transaction event partition day is required';
    END IF;

    parent_name := 'transaction_events_' || p_class;
    partition_name := parent_name || '_' || to_char(p_day, 'YYYYMMDD');
    IF NOT EXISTS (
        SELECT 1
        FROM pg_inherits
        WHERE inhrelid = to_regclass(format('public.%I', partition_name))
          AND inhparent = to_regclass(format('public.%I', parent_name))
    ) THEN
        RETURN FALSE;
    END IF;

    EXECUTE format(
        'ALTER TABLE public.%I DETACH PARTITION public.%I',
        parent_name,
        partition_name
    );
    RETURN TRUE;
END;
$$;

CREATE FUNCTION public.transaction_events_drop_detached_partition(p_class text, p_day date) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    partition_name TEXT;
    partition_oid REGCLASS;
BEGIN
    IF p_class IS NULL OR p_class NOT IN ('hot', 'warm', 'cold') THEN
        RAISE EXCEPTION 'unknown transaction event retention class: %', p_class;
    END IF;
    IF p_day IS NULL THEN
        RAISE EXCEPTION 'transaction event partition day is required';
    END IF;

    partition_name := 'transaction_events_' || p_class || '_' || to_char(p_day, 'YYYYMMDD');
    partition_oid := to_regclass(format('public.%I', partition_name));
    IF partition_oid IS NULL THEN
        RETURN FALSE;
    END IF;
    IF EXISTS (SELECT 1 FROM pg_class WHERE oid = partition_oid AND relispartition) THEN
        RAISE EXCEPTION 'transaction event partition % is still attached', partition_name;
    END IF;

    EXECUTE format('DROP TABLE public.%I', partition_name);
    RETURN TRUE;
END;
$$;

CREATE TABLE public.transaction_events (
    event_id text NOT NULL,
    schema_version text NOT NULL,
    event_time timestamp with time zone NOT NULL,
    event_date date NOT NULL,
    ingested_at timestamp with time zone DEFAULT now() NOT NULL,
    retention_class text NOT NULL,
    producer text NOT NULL,
    event_type text NOT NULL,
    network text,
    tx_hash text,
    block_hash text,
    block_number bigint,
    payload_id text,
    request_id text,
    data jsonb NOT NULL
)
PARTITION BY LIST (retention_class);

CREATE TABLE public.transaction_events_cold (
    event_id text NOT NULL,
    schema_version text NOT NULL,
    event_time timestamp with time zone NOT NULL,
    event_date date NOT NULL,
    ingested_at timestamp with time zone DEFAULT now() NOT NULL,
    retention_class text NOT NULL,
    producer text NOT NULL,
    event_type text NOT NULL,
    network text,
    tx_hash text,
    block_hash text,
    block_number bigint,
    payload_id text,
    request_id text,
    data jsonb NOT NULL
)
PARTITION BY RANGE (event_date);

CREATE TABLE public.transaction_events_hot (
    event_id text NOT NULL,
    schema_version text NOT NULL,
    event_time timestamp with time zone NOT NULL,
    event_date date NOT NULL,
    ingested_at timestamp with time zone DEFAULT now() NOT NULL,
    retention_class text NOT NULL,
    producer text NOT NULL,
    event_type text NOT NULL,
    network text,
    tx_hash text,
    block_hash text,
    block_number bigint,
    payload_id text,
    request_id text,
    data jsonb NOT NULL
)
PARTITION BY RANGE (event_date);

CREATE TABLE public.transaction_events_warm (
    event_id text NOT NULL,
    schema_version text NOT NULL,
    event_time timestamp with time zone NOT NULL,
    event_date date NOT NULL,
    ingested_at timestamp with time zone DEFAULT now() NOT NULL,
    retention_class text NOT NULL,
    producer text NOT NULL,
    event_type text NOT NULL,
    network text,
    tx_hash text,
    block_hash text,
    block_number bigint,
    payload_id text,
    request_id text,
    data jsonb NOT NULL
)
PARTITION BY RANGE (event_date);

ALTER TABLE ONLY public.transaction_events ATTACH PARTITION public.transaction_events_cold FOR VALUES IN ('cold');

ALTER TABLE ONLY public.transaction_events ATTACH PARTITION public.transaction_events_hot FOR VALUES IN ('hot');

ALTER TABLE ONLY public.transaction_events ATTACH PARTITION public.transaction_events_warm FOR VALUES IN ('warm');

